# doc: // --------------------------------------------------------------------------- // AI enrichment configuration // // Every knob is an env var set in prod-igy.yml, not a config file: github-script // has no YAML parser on the trusted path, and a plain `env:` block stays // greppable and diffable in th
function envFlag(name, fallback) {
  const raw = process.env[name];
  if (raw === undefined || String(raw).trim() === '') return fallback;
  return String(raw).trim().toLowerCase() === 'true';
}

