# doc: Yield decoded JSON objects from a JSONL file. A missing file yields     nothing; an unparsable line is skipped rather than aborting the read.
def read_jsonl(path: str):
    """Yield decoded JSON objects from a JSONL file. A missing file yields
    nothing; an unparsable line is skipped rather than aborting the read."""
    try:
        text = Path(path).read_text(encoding="utf8")
    except OSError:
        return
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            continue
        if isinstance(obj, dict):
            yield obj

