# calls: repo2graph/cache.py::ResultCache.get (confidence 0.5), repo2graph/tasks.py::TaskManager.get (confidence 0.5), repo2graph/embed.py::Embedder.encode (confidence 0.5), repo2graph/embed.py::_SentenceTransformerEmbedder.encode (confidence 0.5)
# calls (outside the repo): float, append, max, int, range, len, list, ValueError, zip
# doc: {chunk id: vector} for every chunk, embedding in batches.      `reuse` is an optional {chunk id: vector} of vectors already known to be     current (see cli.cmd_embed); those chunks are never handed to the embedder.
def build_vectors(
    chunks, embedder, batch: int = DEFAULT_BATCH, reuse=None
) -> dict[str, list[float]]:
    """{chunk id: vector} for every chunk, embedding in batches.

    `reuse` is an optional {chunk id: vector} of vectors already known to be
    current (see cli.cmd_embed); those chunks are never handed to the embedder.
    """
    reuse = reuse or {}
    out: dict[str, list[float]] = {}
    todo = []
    for c in chunks:
        cid = c.get("id")
        if not cid:
            continue
        known = reuse.get(cid)
        if known is not None:
            out[cid] = [float(x) for x in known]
        else:
            todo.append(c)
    step = max(1, int(batch))
    for i in range(0, len(todo), step):
        part = todo[i : i + step]
        encoded = list(embedder.encode([c.get("text") or "" for c in part]))
        if len(encoded) != len(part):
            raise ValueError(f"embedder returned {len(encoded)} vectors for {len(part)} texts")
        for c, vec in zip(part, encoded, strict=True):
            out[c["id"]] = [float(x) for x in vec]
    return out

