                "transparent": "false",
            },
        )
        ET.SubElement(
            shape, f"{{{Y_NS}}}BorderStyle", {"color": "#4a4f57", "type": "line", "width": "1.0"}
        )
        text = ET.SubElement(
            shape,
            f"{{{Y_NS}}}NodeLabel",
            {"alignment": "center", "fontSize": "11", "textColor": "#1c2330", "visible": "true"},
