# doc: Return True if a process with `pid` is currently running on the local host.
def _is_pid_alive(pid: int) -> bool:
    """Return True if a process with `pid` is currently running on the local host."""
    if pid <= 0:
        return False
    if sys.platform != "win32":
        try:
            os.kill(pid, 0)
            return True
        except ProcessLookupError:
            return False
        except PermissionError:
            return True
        except OSError:
            return False
    else:
        # Windows process check
        try:
            import ctypes
            from ctypes import wintypes

            kernel32 = getattr(ctypes, "windll").kernel32
            # PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            SYNCHRONIZE = 0x00100000
            PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            handle = kernel32.OpenProcess(
                PROCESS_QUERY_LIMITED_INFORMATION | SYNCHRONIZE, False, wintypes.DWORD(pid)
            )
            if not handle:
                return False
            exit_code = wintypes.DWORD()
            # STILL_ACTIVE = 259
            if kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code)):
                kernel32.CloseHandle(handle)
                return bool(exit_code.value == 259)
            kernel32.CloseHandle(handle)
            return False
        except Exception:
            return True

