def parse_semver(v: str) -> tuple[int, int, int]:
    clean = v.lstrip("v").strip()
    parts = clean.split(".")
    if len(parts) != 3 or not all(p.isdigit() for p in parts):
        raise ValueError(f"Invalid semver version: {v!r}")
    return int(parts[0]), int(parts[1]), int(parts[2])

